class Solution{
    public:
    bool func(int index , int currentSum , vector<int>& nums , int k){

        // base case : Success :
        if(currentSum == k){
            return true ;
        }

        // base case : Failure :
        if(index == nums.size()){
            return false ;
        }

        // exclude :
        bool exclude = func(index + 1 , currentSum , nums , k) ;

        //include:
        bool include = func(index + 1 , currentSum + nums[index] , nums , k) ;

        return exclude || include ;
    }

    bool checkSubsequenceSum(vector<int>& nums, int k) {

         return func(0 , 0 , nums , k) ;
    }
};
